class Array {
public:
    Array(int size);          // implicit converting constructor
};
void print(const Array& a);

print(10);      // compiles: builds a temporary Array(10)
Array a = 5;    // compiles too

class Array {
public:
    explicit Array(int size);
};

print(10);          // no implicit conversion
Array a = 5;        // copy-init needs implicit
Array b(5);         // ok: direct initialization
print(Array(10));   // ok: you asked for it
